    'register.policy.privacy1.title': '1. Thông tin chúng tôi thu thập',
    'register.policy.privacy1.desc': 'Khi bạn đăng ký và sử dụng Academic Research Sharing (ARS), chúng tôi thu thập các loại thông tin sau:',
    'register.policy.privacy1.l1.strong': 'Tài khoản Identity:',
    'register.policy.privacy1.l1.text': 'Full Tên, Email Address, Contact Phone Number, and Password.',
